export { initialTouchDistance, maxZoom, minZoom, touchCenterDivisor, touchPointIndexFirst, touchPointIndexSecond, touchPointsCount, zoomGestureFactor, zoomInFactor, zoomOutFactor, } from "./Utils/Constants.js";
